mapper.select:
select supplier.id as id,
supplier.create_time as informantDateTime,
supplier.informant_date_time as informantDateTime,
supplier.deadline_for_acceptance_time as deadlineForAcceptanceTime, enter.business_name as businessName, enter.liaisons as liaisons, enter.id as crmEnterpriseWarehousingId, enter.country_id as countryId, enter.country_name as countryName, enter.address as address, enter.province_id as provinceId, enter.province_name as provinceName, enter.city_id as cityId, enter.qualification_and_ability as qualificationAndAbility, enter.city_name as cityName, enter.region_id as regionId, enter.region_name as regionName, enter.credit_code as creditCode, supplier.country_name as countryName, supplier.province_name as provinceName, supplier.city_name as cityName, supplier.region_name as regionName, basice_config1.name as unitPropertyAllocationConfigName, basice_config1.id as unitPropertyAllocationConfigId, basice_config2.name as unitClassConfigurationName, basice_config2.id as unitClassConfigurationId, basice_config3.name as industryConfigurationName, basice_config3.id as industryConfigurationId, basice_config4.name as unitReputationAllocationConfigName, basice_config4.id as unitReputationAllocationConfigId, user_b.name as informantUserName, user_a.name as createUserName, supplier.attachment_ids as attachmentIdsByString, enter.business_phone as businessPhone, enter.business_email as businessEmail, warehousing.project_name as projectName from crm_supplier_warehousing as supplier left join crm_project_information_warehousing as warehousing on warehousing.id = supplier.crm_project_information_warehousing_id and warehousing.bool_delete_enum = 0 left join crm_enterprise_warehousing as enter on enter.id = supplier.crm_enterprise_warehousing_id and enter.bool_delete_enum = 0 left join crm_basics_config as basice_config1 on basice_config1.id = enter.unit_property_allocation_config_id and basice_config1.bool_delete_enum = 0 left join crm_basics_config as basice_config2 on basice_config2.id = enter.unit_class_configuration_id and basice_config2.bool_delete_enum = 0 left join crm_basics_config as basice_config3 on basice_config3.id = enter.industry_configuration_id and basice_config3.bool_delete_enum = 0 left join crm_basics_config as basice_config4 on basice_config4.id = enter.unit_reputation_allocation_config_id and basice_config4.bool_delete_enum = 0 left join sys_user as user_a on user_a.id = supplier.create_user_id and user_a.bool_delete_enum = 0 left join sys_user as user_b on user_b.id = supplier.informant_user_id and user_b.bool_delete_enum = 0
supplier.bool_delete_enum =0
and supplier.crm_check_status_enum = #{crmCheckStatusEnum}
and supplier.crm_record_type_enum = #{checkRecord}
and DATE_FORMAT(supplier.create_time, '%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(supplier.create_time, '%Y-%m-%d') <= #{endDate}
and DATE_FORMAT(supplier.informant_date_time, '%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(supplier.informant_date_time, '%Y-%m-%d') <= #{endDate}
and supplier.countr_id = #{countryId}
and supplier.province_id = #{provinceId}
and supplier.city_id = #{cityId}
and supplier.region_id = #{regionId}
and enter.unit_property_allocation_config_id = #{unitPropertyAllocationConfigId}
and enter.unit_class_configuration_id = #{unitClassConfigurationId}
and enter.industry_configuration_id = #{industryConfigurationId}
and enter.unit_reputation_allocation_config_id = #{unitReputationAllocationConfigId}
and enter.business_name like concat('%',#{businessName},'%')
and enter.credit_code like concat('%',#{creditCode},'%')
and user_a.name like concat('%',#{informantUserName},'%')
order by supplier.create_time desc
order by supplier.informant_date_time desc
